const inp = $input.first().json || {};
const eventoId = String(inp.evento_id || '').trim();
const contacto = String(inp.numero_contacto || '').replace(/\D/g, '');
const wa = String(inp.wa_number || '').replace(/\D/g, '');
const sourceMsgId = String(inp.source_message_id || '').trim();
const dryRun = Boolean(inp.dry_run);

if (!eventoId) {
  throw new Error('FALTA_EVENTO: evento_id es obligatorio para proponer la cancelacion.');
}
if (!contacto) {
  throw new Error('FALTA_CONTACTO: numero_contacto es obligatorio.');
}

const payload = {
  wa_number: wa || null,
  contact_number: contacto,
  source_message_id: sourceMsgId || null,
  kind: 'cancel',
  event_id: eventoId,
  dry_run: dryRun
};

return [{ json: payload }];

const resp = $input.first().json || {};
const prep = $('Preparar Propuesta Cancelacion').first().json || {};
const ok = resp.ok === true;
const proposalId = resp.proposal_id || null;
const state = resp.state || (ok ? 'pending_owner_confirmation' : 'blocked');
const msg = resp.message || (ok
  ? `Propuesta de cancelación de cita (${prep.event_id}) enviada a Alek para confirmación.`
  : `No se pudo generar la propuesta de cancelación: ${resp.error || 'error desconocido'}`);

return [{
  json: {
    ok,
    estado: ok ? 'propuesta_cancelacion_creada' : 'error_propuesta',
    state,
    proposal_id: proposalId,
    event_id: prep.event_id,
    mensaje: msg,
    requires_owner_tap: ok && state === 'pending_owner_confirmation'
  }
}];

const raw = $input.first().json || {};
const headers = raw.headers || {};
const auth = headers.authorization || headers.Authorization || '';
const expected = $env.N8N_CALENDAR_TOKEN;

if (!expected || auth !== `Bearer ${expected}`) {
  throw new Error('AUTH_FAILED: agenda local requiere bearer token valido de N8N_CALENDAR_TOKEN');
}

const inp = raw.body || raw;
const confirmado = String(inp.confirmado_por_owner || '').toLowerCase() === 'true';
if (!confirmado) {
  throw new Error('CONFIRMACION_REQUERIDA: cancelar borra el evento del calendario real de Alek. Requiere confirmacion del owner.');
}

const eventoId = String(inp.evento_id || inp.event_id || inp.calendarEventId || '').trim();
if (!eventoId) {
  throw new Error('FALTA_EVENTO: evento_id es obligatorio para cancelar.');
}
const zoomId = String(inp.zoom_id || inp.zoomMeetingId || '').trim();
const opId = String(inp.operation_id || inp.proposal_id || '').trim();

return [{
  json: {
    calendarEventId: eventoId,
    zoomMeetingId: zoomId,
    operation_id: opId || null
  }
}];

const prep = $('Preparar Cancelacion').first().json;
const respuesta = $('Cancelar Calendar y Zoom').first().json || {};
const codigo = Number(respuesta.statusCode || 0);
const rawBody = respuesta.body || respuesta;
const dbRow = $input.first() ? ($input.first().json || {}) : {};

const providerDeleted = (codigo >= 200 && codigo < 300) || rawBody.verified === true;
const dbDeleted = Boolean(dbRow && dbRow.token);
const verified = Boolean(providerDeleted && dbDeleted);

return [{
  json: {
    ok: verified,
    verified,
    state: verified ? 'cancelada' : (providerDeleted ? 'incierta' : 'no_cancelada'),
    estado: verified ? 'cancelada' : 'no_cancelada',
    event_id: prep.calendarEventId,
    enlace_retirado: dbDeleted,
    provider_verified: providerDeleted,
    db_deleted: dbDeleted
  }
}];
